import{_ as a,c as d,o as e,b0 as s}from"./chunks/framework.C5ev1SXp.js";const o="/scm-docs/assets/flash-sram-map.CXgpGWK0.svg",i="/scm-docs/assets/sram-load-flow.Cutw1Agj.svg",u=JSON.parse('{"title":"LV035-SRAM APP设计","description":null,"frontmatter":{"title":"LV035-SRAM APP设计","date":"2026-10-17T19:25:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/online-upgrade/iap/126b0f2764e7a002b543b","index":true,"tags":null,"categories":["在线升级"],"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-17T19:25:00.600Z","fulluuid":"a002b543b2764e7282fe26b27ef1c96e","useduuid":"a002b543b"}},"headers":[],"relativePath":"sdoc/online-upgrade/iap/126b0f2764e7a002b543b.md","filePath":"sdoc/70-在线升级/01-IAP/LV035-SRAM-APP设计.md","lastUpdated":1792231946000}'),r={name:"sdoc/online-upgrade/iap/126b0f2764e7a002b543b.md"};function l(n,t,c,h,p,b){return e(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="lv035-sram-app设计" tabindex="-1">LV035-SRAM APP设计 <a class="header-anchor" href="#lv035-sram-app设计" aria-label="Permalink to &quot;LV035-SRAM APP设计&quot;">​</a></h1><h2 id="一、-运行原理" tabindex="-1">一、 运行原理 <a class="header-anchor" href="#一、-运行原理" aria-label="Permalink to &quot;一、 运行原理&quot;">​</a></h2><h3 id="_1-为什么代码可以直接在-sram-里跑" tabindex="-1">1. 为什么代码可以直接在 SRAM 里跑 <a class="header-anchor" href="#_1-为什么代码可以直接在-sram-里跑" aria-label="Permalink to &quot;1. 为什么代码可以直接在 SRAM 里跑&quot;">​</a></h3><p>Cortex-M3 的取指只看地址落在哪个总线区域：<code>0x20000000</code> 起是 SRAM，挂在 D-bus / I-bus 上，同样可以被取指。只要满足三个条件，代码在哪块可以随机访问的存储器里都能执行：</p><ul><li>链接时的执行地址就是实际装载地址（位置相关代码，不能被搬运到别处）；</li><li>镜像的向量表在运行时被 <code>SCB-&gt;VTOR</code> 指向，中断才能找到处理函数；</li><li>装载完成后按向量表把 MSP 换成镜像自己的栈顶。</li></ul><p><code>sram-app</code> 就是把这三点做到位的一个普通工程，没有任何&quot;特殊运行方式&quot;。它唯一特殊的地方在于：<strong>运行位置不是落盘位置</strong>。</p><h3 id="_2-掉电即失" tabindex="-1">2. 掉电即失 <a class="header-anchor" href="#_2-掉电即失" aria-label="Permalink to &quot;2. 掉电即失&quot;">​</a></h3><p>SRAM 是易失介质，<code>sram-app</code> 一旦断电就没了，重新上电后 <code>0x20007000</code> 处是随机值。所以它不能像 <code>flash-app</code> 那样&quot;烧一次、上电就跑&quot;，每次都要经过一次装载：</p><table tabindex="0"><thead><tr><th>阶段</th><th>介质</th><th>谁来做</th></tr></thead><tbody><tr><td>保存</td><td>内部 Flash 第 3 块 <code>0x08040000</code></td><td>Bootloader 收到 <code>app.img</code> 后写入</td></tr><tr><td>装载</td><td>内部 SRAM <code>0x20007000</code></td><td>Bootloader 收到 <code>go sram</code> 后整块 <code>memcpy</code></td></tr><tr><td>运行</td><td>内部 SRAM <code>0x20007000</code></td><td>跳转后由镜像自己执行</td></tr></tbody></table><p>掉电后 Flash 里的那一份还在，重新上电发一条 <code>go sram</code> 就能再装载一次，不必重发镜像。这是把&quot;暂存区&quot;放进 Flash、而不是&quot;收完直接写 SRAM&quot;的直接收益。</p><h3 id="_3-两条进入途径" tabindex="-1">3. 两条进入途径 <a class="header-anchor" href="#_3-两条进入途径" aria-label="Permalink to &quot;3. 两条进入途径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>途径</th><th>谁触发</th><th>发生了什么</th></tr></thead><tbody><tr><td>IAP 装载</td><td>串口/TCP 发 <code>app.img</code>，再发 <code>go sram</code></td><td>写暂存区 → 校验 → 拷进 SRAM → 跳转</td></tr><tr><td>调试器直接下载</td><td><code>sram-app-debug</code> + SWD</td><td>链接在 <code>0x08000000</code>，下载后上电即跑，用于验证业务逻辑</td></tr></tbody></table><p>第二条途径用的是另一个 Target，链接地址不同，跑起来占的是 Flash 第 1 块——它会覆盖 Bootloader，所以只用于&quot;先把业务代码调通&quot;的阶段。</p><h2 id="二、-链接地址" tabindex="-1">二、 链接地址 <a class="header-anchor" href="#二、-链接地址" aria-label="Permalink to &quot;二、 链接地址&quot;">​</a></h2><h3 id="_1-irom1-与-iram1" tabindex="-1">1. IROM1 与 IRAM1 <a class="header-anchor" href="#_1-irom1-与-iram1" aria-label="Permalink to &quot;1. IROM1 与 IRAM1&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td>IROM1（代码容器）</td><td><code>0x20007000</code>，大小 <code>0x6000</code>（24KB）</td><td>镜像装载与执行的位置</td></tr><tr><td>IRAM1（数据区）</td><td><code>0x2000D000</code>，大小 <code>0x2C00</code>（11KB）</td><td><code>.data</code>/<code>.bss</code>/堆/栈</td></tr><tr><td>栈顶</td><td><code>0x2000FC00</code></td><td>由向量表第 1 项给出</td></tr><tr><td>NOINIT</td><td><code>0x2000FC00</code> 起 1KB</td><td>复位不清零的保留区，Bootloader 与 APP 共用约定</td></tr></tbody></table><p><img src="'+o+`" alt="内部 FLASH 与 SRAM 地址分区"></p><h3 id="_2-三个边界为什么这样切" tabindex="-1">2. 三个边界为什么这样切 <a class="header-anchor" href="#_2-三个边界为什么这样切" aria-label="Permalink to &quot;2. 三个边界为什么这样切&quot;">​</a></h3><ul><li><code>0x20000000</code> ~ <code>0x20007000</code> 留给 Bootloader：它的 RW/ZI 实际用到 <code>0x20005E18</code>，剩下的空间是余量，不能拿来放 APP；</li><li><code>0x20007000</code> ~ <code>0x2000D000</code> 正好 24KB，是代码容器。取整到 4KB 边界是为了页对齐和调试查看方便；</li><li><code>0x2000D000</code> ~ <code>0x2000FC00</code> 放 APP 的全局变量与栈，与代码区隔开，避免栈溢出直接把指令覆盖掉（栈溢出会先撞到 NOINIT 区，症状比重叠代码更好查）。</li></ul><h3 id="_3-三处必须同步" tabindex="-1">3. 三处必须同步 <a class="header-anchor" href="#_3-三处必须同步" aria-label="Permalink to &quot;3. 三处必须同步&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>内容</th><th>不同步的后果</th></tr></thead><tbody><tr><td><code>sram-app.uvprojx</code> 的 IROM1</td><td><code>0x20007000</code> / <code>0x6000</code></td><td>链接出的镜像按错误地址编址，装载后必然跑飞</td></tr><tr><td><code>iap.h</code> 的 <code>IAP_SRAM_APP_BASE/MAX_SIZE</code></td><td><code>0x20007000</code> / 24KB</td><td>帧头地址校验拒绝，或搬运越界</td></tr><tr><td><code>pack_iap.py</code> 的 <code>SRAM_APP_BASE/END</code></td><td>同上</td><td>打包时就报 <code>address or size out of range</code></td></tr></tbody></table><h2 id="三、-功能说明" tabindex="-1">三、 功能说明 <a class="header-anchor" href="#三、-功能说明" aria-label="Permalink to &quot;三、 功能说明&quot;">​</a></h2><h3 id="_1-功能清单" tabindex="-1">1. 功能清单 <a class="header-anchor" href="#_1-功能清单" aria-label="Permalink to &quot;1. 功能清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>串口日志</td><td>与 <code>flash-app</code> 相同，115200，<code>fputc</code> 轮询发送</td></tr><tr><td>行命令 <code>reboot</code></td><td>打印后等 <code>TC</code>，软复位回 Bootloader</td></tr><tr><td>串口回显</td><td>收到整行原样回发，用于验证装载后外设是否正常</td></tr><tr><td>看门狗</td><td><code>iwdg_start()</code> 后主循环喂狗，3 秒超时</td></tr><tr><td>网络</td><td>无</td></tr></tbody></table><h3 id="_2-与-flash-app-的差异" tabindex="-1">2. 与 FLASH APP 的差异 <a class="header-anchor" href="#_2-与-flash-app-的差异" aria-label="Permalink to &quot;2. 与 FLASH APP 的差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th><code>flash-app</code></th><th><code>sram-app</code></th></tr></thead><tbody><tr><td>链接地址</td><td><code>0x08020000</code></td><td><code>0x20007000</code></td></tr><tr><td>落盘位置</td><td>就是运行位置</td><td><code>0x08040000</code> 暂存</td></tr><tr><td>掉电后</td><td>内容保留</td><td>内容丢失，需重新 <code>go sram</code></td></tr><tr><td>装载步骤</td><td>写完即可跳</td><td>写完还要搬运、回读校验</td></tr><tr><td>调试豁免</td><td><code>flash-app-debug</code> 链接 <code>0x08000000</code></td><td><code>sram-app-debug</code> 同样链接 <code>0x08000000</code></td></tr><tr><td>代码体积上限</td><td>128KB</td><td>24KB（容器限制）</td></tr></tbody></table><p>24KB 的上限是实打实的约束：一旦业务代码把 <code>.text</code> 撑到 24KB 以上，链接阶段就会报 region 溢出，此时只能压缩代码或改分区。</p><h2 id="四、-启动与向量表" tabindex="-1">四、 启动与向量表 <a class="header-anchor" href="#四、-启动与向量表" aria-label="Permalink to &quot;四、 启动与向量表&quot;">​</a></h2><h3 id="_1-进入-main-之前" tabindex="-1">1. 进入 main 之前 <a class="header-anchor" href="#_1-进入-main-之前" aria-label="Permalink to &quot;1. 进入 main 之前&quot;">​</a></h3><p>跳转是&quot;硬跳&quot;：Bootloader 读暂存区向量表拿到 MSP 与复位向量，设好 <code>SCB-&gt;VTOR</code>，<code>__set_MSP()</code>，然后跳到 <code>Reset_Handler</code>。于是 <code>sram-app</code> 的启动流程与普通 Flash 启动完全一致：</p><p>（1）<code>Reset_Handler</code> 调 <code>SystemInit()</code>，配时钟与 Flash 预取；</p><p>（2）<code>__main</code> 把 <code>.data</code> 初值从镜像里拷到 <code>0x2000D000</code> 起，把 <code>.bss</code> 清零；</p><p>（3）<code>main()</code> 里第一件事是把 VTOR 指向自己。</p><h3 id="_2-vtor-必须在-hal-init-之前" tabindex="-1">2. VTOR 必须在 HAL_Init 之前 <a class="header-anchor" href="#_2-vtor-必须在-hal-init-之前" aria-label="Permalink to &quot;2. VTOR 必须在 HAL_Init 之前&quot;">​</a></h3><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// sram-app/Core/Src/main.c</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifndef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> APP_BASE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> APP_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20007000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* IAP_SRAM_APP_BASE: 与 IROM1 / pack_iap.py 一致 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 向量表重定位到 APP 基址: 必须早于 HAL_Init(), 否则中断仍会走 Bootloader 的向量表 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SCB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VTOR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> APP_BASE;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAL_Init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><code>HAL_Init()</code> 里会配 SysTick 并开中断，如果那时 VTOR 还没改，SysTick 中断会按 Bootloader 的向量表跳到 <code>0x08000000 + 0x3C</code>——落进 Bootloader 的代码里，症状是随机 HardFault 或&quot;程序莫名跑回 Bootloader&quot;。</p><p>同样的道理，<code>SystemInit()</code> 里也不要依赖中断：它执行时 VTOR 还是 Bootloader 设的值（恰好正确），但一旦有别的镜像经由其它路径进入，就会踩到同一个坑。</p><h3 id="_3-中断都落在-sram-里" tabindex="-1">3. 中断都落在 SRAM 里 <a class="header-anchor" href="#_3-中断都落在-sram-里" aria-label="Permalink to &quot;3. 中断都落在 SRAM 里&quot;">​</a></h3><p>VTOR 指向 <code>0x20007000</code> 之后，所有异常向量都指向 SRAM 中的处理函数。这也意味着<strong>装载完成前不能开中断</strong>：Bootloader 在 <code>memcpy</code> 期间保持自己的中断设置，拷完校验通过才切 VTOR 并跳转。</p><h2 id="五、-构建与装载" tabindex="-1">五、 构建与装载 <a class="header-anchor" href="#五、-构建与装载" aria-label="Permalink to &quot;五、 构建与装载&quot;">​</a></h2><h3 id="_1-构建" tabindex="-1">1. 构建 <a class="header-anchor" href="#_1-构建" aria-label="Permalink to &quot;1. 构建&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># release: 链接 0x20007000，构建后由 pack_iap.py -a 0x20007000 打成 app.img</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build_sram.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 调试: 链接 0x08000000，可 SWD 直接下载运行</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build_sram.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t debug </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>release 构建的产物序列是：<code>sram-app.axf</code> → <code>fromelf --bin</code> → <code>sram-app.bin</code> → <code>pack_iap.py -a 0x20007000</code> → <code>app.img</code>。</p><h3 id="_2-装载流程" tabindex="-1">2. 装载流程 <a class="header-anchor" href="#_2-装载流程" aria-label="Permalink to &quot;2. 装载流程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>命令</th><th>校验</th></tr></thead><tbody><tr><td>写入暂存区</td><td>发 <code>app.img</code>（串口或 TCP）</td><td>帧 CRC32 + 回读 CRC32</td></tr><tr><td>搬运</td><td><code>go sram</code></td><td>向量表三条判据 + 搬运后 CRC32</td></tr><tr><td>跳转</td><td>同上</td><td><code>iap_load_app(0x20007000)</code> 再查一次向量表</td></tr></tbody></table><p>搬运这一步的细节值得单独看清：从 Flash 暂存区到 SRAM 容器是<strong>两块不同介质</strong>之间的拷贝，长度固定取容器容量 24KB（24576 字节），而不是帧头里记录的实际长度——暂存区没写到的尾部是 <code>0xFF</code>，落在容器内永远不会被执行到。</p><p><img src="`+i+'" alt="SRAM APP 的搬运与跳转流程"></p><h3 id="_3-常见问题" tabindex="-1">3. 常见问题 <a class="header-anchor" href="#_3-常见问题" aria-label="Permalink to &quot;3. 常见问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>go sram</code> 提示 <code>no sram-app image in flash staging</code></td><td>暂存区没写过</td><td>先发 <code>app.img</code>，确认落盘成功</td></tr><tr><td>跳转后立即 HardFault</td><td>镜像按 <code>0x08000000</code> 链接（用了 debug Target）</td><td>用 release 构建重新打包</td></tr><tr><td>运行一段时间后复位</td><td>24KB 容器被写穿，或看门狗未喂</td><td>查 <code>.map</code> 的 region 占用与喂狗周期</td></tr><tr><td>复位后 APP 消失</td><td>正常现象，SRAM 易失</td><td>重新发 <code>go sram</code></td></tr><tr><td>中断进了 Bootloader 的处理函数</td><td>VTOR 未在 <code>HAL_Init()</code> 之前设置</td><td>检查 <code>main()</code> 开头的 <code>SCB-&gt;VTOR = APP_BASE</code></td></tr></tbody></table><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',51)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
